// Import the functions you need from the SDKs you need
import { initializeApp, getApps, getApp } from "firebase/app";
import { getAuth, GoogleAuthProvider } from "firebase/auth";
import {
  collection,
  doc,
  getDocs,
  getFirestore,
  updateDoc,
} from "firebase/firestore";
import {
  userConfig,
  FirebaseConfig,
  SHARED_PROJECT_KEY,
  isSharedTenantUser,
} from "../config/userConfig";

export type { FirebaseConfig };

const firebaseConfigs: Record<string, FirebaseConfig> = Object.fromEntries(
  Object.entries(userConfig)
    .filter(([, value]) => value.firebase)
    .map(([key, value]) => [key, value.firebase as FirebaseConfig])
);

export const firebaseUsers = Object.keys(firebaseConfigs);

// Users without a dedicated `firebase` block resolve to the shared project's
// app/config instead, so they never need their own Firebase project.
const resolveProjectKey = (userId: string) =>
  isSharedTenantUser(userId) ? SHARED_PROJECT_KEY : userId;

// Store initialized apps
const firebaseInstances: Record<string, any> = {};

// Function to get or initialize a Firebase app
export const getFirebaseApp = (projectKey: string = "manish") => {
  const resolvedKey = resolveProjectKey(projectKey);
  if (!firebaseInstances[resolvedKey]) {
    const apps = getApps();
    if (apps.some((app) => app.name === resolvedKey)) {
      firebaseInstances[resolvedKey] = getApp(resolvedKey);
    } else {
      firebaseInstances[resolvedKey] = initializeApp(
        firebaseConfigs[resolvedKey],
        resolvedKey
      );
    }
  }
  return firebaseInstances[resolvedKey];
};

// Function to get Firebase services for a specific app
export const getFirebaseServices = (projectKey: string = "manish") => {
  const app = getFirebaseApp(projectKey);
  return {
    auth: getAuth(app),
    googleProvider: new GoogleAuthProvider(),
    db: getFirestore(app),
  };
};

// The value to tag/filter Firestore docs by for users sharing the pooled
// project. Returns undefined for users with their own dedicated project —
// their data is already isolated by database, no field needed.
export const getDataScopeUserId = (userId: string): string | undefined =>
  isSharedTenantUser(userId) ? userId : undefined;

export const addAttributeToCollection = async (
  projectKey: string = "manish",
  collectionName: string,
  attributeName: string,
  attributeValue: any
) => {
  try {
    const { db } = getFirebaseServices(projectKey);
    const colRef = collection(db, collectionName);
    const snapshot = await getDocs(colRef);

    const updatePromises = snapshot.docs.map((docSnap) => {
      const docRef = doc(db, collectionName, docSnap.id);
      return updateDoc(docRef, { [attributeName]: attributeValue });
    });

    await Promise.all(updatePromises);
  } catch (error) {
    console.error("Error adding attribute to collection:", error);
  }
};

