import React, { useState } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Box,
  Container,
  Button,
} from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import LogoutIcon from "@mui/icons-material/PowerSettingsNew";

import { getFirebaseServices } from "../Firebase/config";
import { signInWithPopup, signOut } from "firebase/auth";
import { useDataStateContext } from "./context/DataStateContext";
import { useFireBase } from "../context/FirebaseConfigContext";

const Header = () => {
  const { dispatch } = useDataStateContext();
  const [user, setUser] = useState<string | undefined | null>();
  const { state } = useFireBase();
  const auth = getFirebaseServices(state.userId).auth;
  const googleProvider = getFirebaseServices(state.userId).googleProvider;

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
      setUser(auth?.currentUser?.displayName);

      dispatch({
        type: "auth",
        payload: auth?.currentUser?.displayName ? true : false,
      });
    } catch (e) {
      console.log(e);
    }
  };

  const signOutWithGoogle = async () => {
    try {
      await signOut(auth);
      dispatch({ type: "auth", payload: false });
    } catch (e) {
      console.log(e);
    }
  };

  return (
    <div>
      <AppBar position="static" color="primary" elevation={2}>
        <Toolbar variant="dense">
          <PersonIcon fontSize="small" style={{ marginRight: 8 }} />
          <Typography variant="h6" style={{ flexGrow: 1 }}>
            Dream Dashboard
          </Typography>
          {!auth?.currentUser?.displayName ? (
            <Button color="inherit" onClick={signInWithGoogle}>
              Sign in
            </Button>
          ) : (
            <IconButton onClick={signOutWithGoogle} size="small">
              <LogoutIcon />
            </IconButton>
          )}
        </Toolbar>
      </AppBar>

      {/* Header only — analytics moved below Category wise data in ItemsList */}
    </div>
  );
};

export default Header;
