import React, { useMemo, useState } from "react";
import { useDataStateContext } from "../context/DataStateContext";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar, Line, Doughnut, Pie } from "react-chartjs-2";
import {
  Box,
  MenuItem,
  Select,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
  Paper,
  Grid,
  Button,
  CircularProgress,
} from "@mui/material";
import "./analytics.scss";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  ArcElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
);

const rangeOptions = [7, 30, 90, 365];

const Analytics: React.FC = () => {
  const { state } = useDataStateContext();
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [range, setRange] = useState<number>(30);
  const [version, setVersion] = useState<number>(0);

  const items = state?.items || [];
  const categories = state?.category || [];
  const isLoading = !!(state?.loading?.items || state?.loading?.category);

  // Filtered items by selected category and date range
  const filteredItems = useMemo(() => {
    const minDate = Date.now() - range * 24 * 60 * 60 * 1000;
    return items.filter((it) => {
      const withinCategory =
        selectedCategory === "all" || it.category === selectedCategory;
      const withinRange = new Date(it.date).getTime() >= minDate;
      return withinCategory && withinRange;
    });
  }, [items, selectedCategory, range, version]);

  // If no items match the filters, fall back to using all items so charts
  // render meaningful data (prevents empty charts when date range is narrow).
  const displayItems = useMemo(() => {
    return filteredItems && filteredItems.length > 0 ? filteredItems : items;
  }, [filteredItems, items]);

  // Items per category for bar/doughnut — use filtered items so charts reflect
  // the selected date range and category filter.
  const itemsPerCategory = useMemo(() => {
    const map = new Map<string, { count: number; amount: number }>();
    // ensure we have keys for known categories and any categories present in filtered items
    categories.forEach((c) => c?.id && map.set(c.id, { count: 0, amount: 0 }));
    displayItems.forEach((it) => {
      const entry = map.get(it.category) || { count: 0, amount: 0 };
      entry.count += 1;
      entry.amount += parseFloat(String(it.price || 0));
      map.set(it.category, entry);
    });
    return Array.from(map.entries()).map(([categoryId, stats]) => ({
      categoryId,
      name:
        categories.find((c) => c.id === categoryId)?.name || "Uncategorized",
      ...stats,
    }));
  }, [displayItems, categories, version]);

  const barData = useMemo(() => {
    const labels = itemsPerCategory.map((c) => c.name);
    const data = itemsPerCategory.map((c) => c.amount);
    return {
      labels,
      datasets: [
        {
          label: "Total Amount",
          data,
          backgroundColor: "rgba(63,81,181,0.7)",
        },
      ],
    };
  }, [itemsPerCategory]);

  const doughnutData = useMemo(() => {
    const labels = itemsPerCategory.map((c) => c.name);
    const data = itemsPerCategory.map((c) => c.count);
    return {
      labels,
      datasets: [
        {
          label: "Items Count",
          data,
          backgroundColor: [
            "#3f51b5",
            "#ff9800",
            "#4caf50",
            "#f44336",
            "#9c27b0",
          ],
        },
      ],
    };
  }, [itemsPerCategory]);

  // Payment mode breakdown (pie)
  const paymentModeData = useMemo(() => {
    const map = new Map<string, number>();
    filteredItems.forEach((it) => {
      const mode = it.pmode || "Unknown";
      map.set(mode, (map.get(mode) || 0) + 1);
    });
    const labels = Array.from(map.keys());
    const data = Array.from(map.values());
    return {
      labels,
      datasets: [
        {
          label: "Payment Modes",
          data,
          backgroundColor: ["#3f51b5", "#ff9800", "#4caf50", "#f44336", "#9c27b0"],
        },
      ],
    };
  }, [filteredItems]);

  // Top 5 items by price (horizontal bar)
  const topItemsData = useMemo(() => {
    const sorted = [...filteredItems]
      .sort((a, b) => parseFloat(String(b.price || 0)) - parseFloat(String(a.price || 0)))
      .slice(0, 5);
    const labels = sorted.map((s) => s.name || "Unnamed");
    const data = sorted.map((s) => parseFloat(String(s.price || 0)));
    return {
      labels,
      datasets: [
        {
          label: "Price",
          data,
          backgroundColor: "rgba(76,175,80,0.7)",
        },
      ],
    };
  }, [filteredItems]);

  const timeseriesData = useMemo(() => {
    // Group by date (day)
    const map = new Map<string, number>();
    filteredItems.forEach((it) => {
      const d = new Date(it.date);
      const key = d.toLocaleDateString();
      map.set(key, (map.get(key) || 0) + 1);
    });
    const sorted = Array.from(map.entries()).sort(
      (a, b) => new Date(a[0]).getTime() - new Date(b[0]).getTime(),
    );
    return {
      labels: sorted.map((s) => s[0]),
      datasets: [
        {
          label: "Items",
          data: sorted.map((s) => s[1]),
          borderColor: "rgba(63,81,181,0.9)",
          backgroundColor: "rgba(63,81,181,0.3)",
          tension: 0.3,
        },
      ],
    };
  }, [filteredItems]);

  const totalAmount = filteredItems.reduce(
    (s, it) => s + parseFloat(String(it.price || 0)),
    0,
  );

  // Automatically bump version when item ids change so charts refresh
  React.useEffect(() => {
    const ids = (items || []).map((i) => i?.id).join(",");
    setVersion((v) => v + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items.length]);

  return (
    <div className="analytics-root">
      <Box mb={2}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={4}>
            <Paper className="stat-card">
              <Typography variant="subtitle2">Total Items</Typography>
              <Typography variant="h5">{filteredItems.length}</Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} md={4}>
            <Paper className="stat-card">
              <Typography variant="subtitle2">Total Amount</Typography>
              <Typography variant="h5">₹ {totalAmount.toFixed(2)}</Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} md={4}>
            <Paper className="stat-card controls">
              <Select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(String(e.target.value))}
                size="small"
              >
                <MenuItem value="all">All categories</MenuItem>
                {categories.map((c) => (
                  <MenuItem key={c.id} value={c.id}>
                    {c.name}
                  </MenuItem>
                ))}
              </Select>
              <ToggleButtonGroup
                value={range}
                exclusive
                onChange={(e, v) => v && setRange(v)}
                size="small"
                className="range-toggle"
              >
                {rangeOptions.map((r) => (
                  <ToggleButton key={r} value={r} aria-label={`${r} days`}>
                    {r === 365 ? "1y" : `${r}d`}
                  </ToggleButton>
                ))}
              </ToggleButtonGroup>
              <Button
                size="small"
                onClick={() => {
                  setSelectedCategory("all");
                  setRange(30);
                }}
              >
                Reset
              </Button>
              <Button
                size="small"
                onClick={() => setVersion((v) => v + 1)}
                style={{ marginLeft: 8 }}
              >
                Refresh Charts
              </Button>
            </Paper>
          </Grid>
        </Grid>
      </Box>

      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <Paper className="chart-card">
            <Typography variant="subtitle1">Amount by Category</Typography>
            {isLoading ? (
              <Box display="flex" justifyContent="center" p={4}>
                <CircularProgress size={28} />
              </Box>
            ) : (
              <Bar data={barData} redraw />
            )}
          </Paper>
        </Grid>
        <Grid item xs={12} md={6}>
          <Paper className="chart-card">
            <Typography variant="subtitle1">Items Distribution</Typography>
            {isLoading ? (
              <Box display="flex" justifyContent="center" p={4}>
                <CircularProgress size={28} />
              </Box>
            ) : (
              <Doughnut data={doughnutData} redraw />
            )}
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper className="chart-card">
            <Typography variant="subtitle1">Payment Mode Breakdown</Typography>
            {isLoading ? (
              <Box display="flex" justifyContent="center" p={4}>
                <CircularProgress size={28} />
              </Box>
            ) : (
              <Pie data={paymentModeData} redraw />
            )}
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper className="chart-card">
            <Typography variant="subtitle1">Top 5 Items by Price</Typography>
            {isLoading ? (
              <Box display="flex" justifyContent="center" p={4}>
                <CircularProgress size={28} />
              </Box>
            ) : (
              <Bar data={topItemsData} options={{ indexAxis: "y" }} redraw />
            )}
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper className="chart-card">
            <Typography variant="subtitle1">Items Over Time</Typography>
            {isLoading ? (
              <Box display="flex" justifyContent="center" p={4}>
                <CircularProgress size={28} />
              </Box>
            ) : (
              <Line data={timeseriesData} redraw />
            )}
          </Paper>
        </Grid>
      </Grid>
    </div>
  );
};

export default Analytics;
