import { getDocs, deleteDoc, updateDoc } from "firebase/firestore";
import { useEffect, useRef, useState } from "react";
import { ICategoryProps } from "../context/DataStateModels";
import { useDataStateContext } from "../context/DataStateContext";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
import {
  categoryDoc,
  categoryList,
  filterOwnDocs,
  scopedQuery,
  TModes,
} from "../Utils/Utils";
import "../Items/items.scss";
import "./Category.scss";
import { Modal } from "../Modal";

import { Table } from "@manish774/smarty-ui";
import { useFireBase } from "../../context/FirebaseConfigContext";
import { getDataScopeUserId, getFirebaseServices } from "../../Firebase/config";

const CategoryList = ({
  refresh,
  handleMode,
}: {
  refresh: () => any;
  handleMode: (newMode: TModes, id: string) => any;
}) => {
  const { dispatch } = useDataStateContext();
  const [category, setCategory] = useState<ICategoryProps[]>([]);
  const [selectedIdToDelete, setSelectedIdToDelete] = useState<string>("");
  const [isDialogOpen, setIsDialogOpen] = useState<boolean>(false);
  const { state: firebaseState } = useFireBase();
  const db = getFirebaseServices(firebaseState.userId).db;
  const scopeUserId = getDataScopeUserId(firebaseState.userId);
  const deleteCategory = async () => {
    if (selectedIdToDelete) {
      await deleteDoc(categoryDoc(selectedIdToDelete, db));
      dispatch({
        type: "addCategory",
        payload: category?.filter((d) => d?.id !== selectedIdToDelete),
      });
      refresh();
    }
  };

  const showDialogBox = (id: string) => {
    setSelectedIdToDelete(id);
    setIsDialogOpen(true);
  };

  useEffect(() => {
    const getCategory = async () => {
      try {
        const data = await getDocs(scopedQuery(categoryList(db), scopeUserId));
        const categoryData = data?.docs?.map((doc) => ({
          ...doc.data(),
          id: doc.id,
          isEdit: false,
          oldValue: doc.data().name,
        }));
        setCategory(
          filterOwnDocs(
            categoryData || [],
            firebaseState.userId
          ) as ICategoryProps[]
        );
      } catch (e) {
        console.log(e);
        setCategory([]);
      }
    };
    getCategory();
  }, [refresh, scopeUserId]);

  const onEdit = (id: string) => {
    handleMode("EDIT", id);
  };

  const sortedCategory = (() => {
    const topLevel = category?.filter((cat) => !cat?.parentId) || [];
    const childrenOf = (parentId?: string) =>
      category?.filter((cat) => cat?.parentId === parentId) || [];
    const ordered: ICategoryProps[] = [];
    topLevel.forEach((parent) => {
      ordered.push(parent);
      childrenOf(parent?.id).forEach((child) => ordered.push(child));
    });
    // orphans: subcategories whose parent no longer exists
    const orderedIds = new Set(ordered.map((cat) => cat?.id));
    category?.forEach((cat) => {
      if (!orderedIds.has(cat?.id)) {
        ordered.push(cat);
      }
    });
    return ordered;
  })();

  return (
    <>
      <Table
        records={sortedCategory}
        config={{
          title: "Category",
          columns: [
            {
              id: "name",
              name: "name",
              searchable: true,
              highLight: {
                bgColor: "rebeccapurple",
                color: "default",
              },
              render: (row) => {
                return (
                  <span style={row?.parentId ? { paddingLeft: "20px" } : {}}>
                    {row?.parentId ? "↳ " : ""}
                    {row?.name}
                  </span>
                );
              },
            },
            {
              id: "edit",
              name: "",
              highLight: {
                bgColor: "rebeccapurple",
                color: "default",
              },
              render: (row) => {
                return (
                  <EditIcon
                    onClick={() => {
                      row.id && onEdit(row?.id);
                    }}
                  />
                );
              },
            },
            {
              id: "delete",
              name: "",
              highLight: {
                bgColor: "rebeccapurple",
                color: "default",
              },
              render: (row) => {
                return (
                  <DeleteIcon
                    onClick={(e) => {
                      e.preventDefault();
                      showDialogBox(row.id);
                    }}
                  />
                );
              },
            },
          ],
          paginationRequired: true,
        }}
        pageSize={10}
      />
      {isDialogOpen && (
        <Modal
          isDialogOpen={isDialogOpen}
          component={
            <>
              Are you sure want to delete{" "}
              <h5 style={{ display: "inline" }}>
                {category?.find((cat) => cat?.id === selectedIdToDelete).name}
              </h5>{" "}
              ?
            </>
          }
          dialogSize={"SMALL"}
          onCloseAction={() => {
            setIsDialogOpen(false);
          }}
          submitClick={() => {
            deleteCategory();
            setIsDialogOpen(false);
            setSelectedIdToDelete("");
          }}
        />
      )}
    </>
    // <Paper sx={{ width: "100%", overflow: "hidden" }}>
    //   <Grid>
    //     <h3>Categories</h3>
    //     <TableContainer component={Paper} sx={{ maxHeight: 440 }}>
    //       <Table stickyHeader aria-label="sticky table">
    //         <TableHead className={"table-header"}>
    //           <TableRow>
    //             {/* <TableCell>Id</TableCell> */}
    //             <TableCell>Name</TableCell>
    //             <TableCell></TableCell>
    //             <TableCell></TableCell>
    //           </TableRow>
    //         </TableHead>
    //         <TableBody>
    //           {(category || []).map((row: ICategoryProps) => (
    //             <TableRow
    //               key={row.id}
    //               sx={{ "&:last-child td, &:last-child th": { border: 0 } }}
    //             >
    //               {/* <TableCell align="left">{row.id}</TableCell> */}
    //               <TableCell align="left">
    //                 <input
    //                   key={row?.id}
    //                   ref={inputRef}
    //                   value={row.name}
    //                   disabled={!row?.isEdit}
    //                   onChange={(e) =>
    //                     row?.id && onChangeHandler(row?.id, e.target?.value)
    //                   }
    //                   className="editCategoryInput"
    //                   id={`edit-${row?.id}`}
    //                   onBlur={(e) => {
    //                     row?.id && saveEditedCategory(row?.id, e.target?.value);
    //                   }}
    //                 />
    //               </TableCell>
    //               <TableCell align="left">
    //                 <DeleteIcon
    //                   onClick={(e) => {
    //                     e.preventDefault();
    //                     showDialogBox(row.id);
    //                   }}
    //                 />
    //               </TableCell>
    //               <TableCell align="left">
    //                 <EditIcon
    //                   onClick={(e) => {
    //                     row.id && onEdit(row?.id);
    //                   }}
    //                 />
    //               </TableCell>
    //             </TableRow>
    //           ))}
    //         </TableBody>
    //       </Table>
    //     </TableContainer>
    //   </Grid>
    // {isDialogOpen && (
    //   <Modal
    //     isDialogOpen={isDialogOpen}
    //     component={
    //       <>
    //         Are you sure want to delete{" "}
    //         <h5 style={{ display: "inline" }}>
    //           {category?.find((cat) => cat?.id === selectedIdToDelete).name}
    //         </h5>{" "}
    //         ?
    //       </>
    //     }
    //     dialogSize={"SMALL"}
    //     onCloseAction={() => {
    //       setIsDialogOpen(false);
    //     }}
    //     submitClick={() => {
    //       deleteCategory();
    //       setIsDialogOpen(false);
    //       setSelectedIdToDelete("");
    //     }}
    //   />
    // )}
    // </Paper>
  );
};

export default CategoryList;
